import {defaults,theory,spectrum} from './spec-model.js';
import {chart} from './charts.js';
const $=s=>document.querySelector(s),fmt=(x,n=4)=>Number.isFinite(x)?Number(x).toPrecision(n):'미산출';
const node=(tag,value)=>{const e=document.createElement(tag);e.textContent=value;return e;};
function table(host,headers,rows){host.replaceChildren();const t=document.createElement('table'),head=document.createElement('tr');headers.forEach(x=>head.append(node('th',x)));t.append(head);for(const values of rows){const tr=document.createElement('tr');values.forEach(x=>tr.append(node('td',x)));t.append(tr);}host.append(t);}
function cards(host,items){host.replaceChildren();for(const [label,value,note]of items){const e=node('div','');e.className='metric-card';e.append(node('small',label),node('strong',value),node('small',note));host.append(e);}}
function envelope(points,buckets=1000){if(points.length<=buckets*2)return points;const out=[];const width=Math.ceil(points.length/buckets);for(let i=0;i<points.length;i+=width){const slice=points.slice(i,i+width);let min=slice[0],max=slice[0];for(const p of slice){if(p[1]<min[1])min=p;if(p[1]>max[1])max=p;}out.push(...[min,max].sort((a,b)=>a[0]-b[0]));}return out;}
function numeric(s){const m=String(s).replace(/[()]/g,'').match(/^([+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:e[+-]?\d+)?)([TGMKkmunpfa]?)/i);if(!m)return NaN;return Number(m[1])*({T:1e12,G:1e9,M:1e6,K:1e3,k:1e3,m:1e-3,u:1e-6,n:1e-9,p:1e-12,f:1e-15,a:1e-18}[m[2]]||1);}
export function registerDashboard({api,getRuns,setRuns}){
 let runs=getRuns(),selected=null,wave=null,model=null,worker=null,loadRevision=0;
 const fields=[['fs','fs [Hz]',1],['OSR','OSR',1],['fin','입력 fin [Hz]',1],['Ain','입력 진폭 [FS]',1],['Vref','Vref [V]',1],['Cs','Cs [pF]',1e12],['Ci','Ci [pF]',1e12],['Cp','Cp [pF]',1e12],['A0','A0 [V/V]',1],['GBW','GBW [MHz]',1e-6],['SR','SR [V/µs]',1e-6],['PM','PM [deg] (가정)',1],['Temp','온도 [K]',1],['nkTC','kT/C 계수',1],['Vsat','출력 포화 [V]',1],['Vhyst','히스테리시스 [mV]',1e3],['jitter','지터 [ps]',1e12],['N','FFT 샘플 수',1],['seed','난수 seed',1]];
 let saved={};try{saved=JSON.parse(localStorage.getItem('circuit-model-conditions')||'{}');}catch{}
 for(const [key,label,scale]of fields){const field=node('label',label),input=document.createElement('input');input.type='number';input.step='any';input.id='model-'+key;input.value=(saved[key]??defaults[key])*scale;input.oninput=()=>{$('#modelStatus').textContent='가정이 바뀌었습니다. 스펙/모델을 다시 계산하세요.';model=null;for(const id of ['modelSpectrum','amplitudeChart','modelSweeps','modelSummary','specTable','theoryCards','noiseTable','settlingTable'])$('#'+id).replaceChildren();};field.append(input);$('#modelInputs').append(field);}
 const read=()=>Object.fromEntries(fields.map(([key,,scale])=>[key,Number($('#model-'+key).value)/scale]));
 let targets={A0:50,GBW:.55,SR:1.96,PM:65,SNDR:60};try{Object.assign(targets,JSON.parse(localStorage.getItem('circuit-spec-targets')||'{}'));}catch{}
 function showTheory(p){const t=theory(p);localStorage.setItem('circuit-model-conditions',JSON.stringify(p));
  cards($('#theoryCards'),[['신호 대역 BW',fmt(t.BW)+' Hz','fs / (2 × OSR)'],['적분기 계수 a',fmt(t.a),'Cs / Ci'],['피드백 팩터 β',fmt(t.beta),'Ci / (Ci + Cs + Cp)'],['이론 SQNR',fmt(t.sqnr)+' dB','1차 1비트 · full-scale 근사'],['적분 위상',fmt(t.Tint*1e6)+' µs','Ts / 2'],['폐루프 τ',fmt(t.tau*1e9)+' ns','단일극 근사']]);
  const rows=[['A0','dB',20*Math.log10(p.A0)],['GBW','MHz',p.GBW/1e6],['SR','V/µs',p.SR/1e6],['PM','deg',p.PM],['SNDR','dB',model?.real.sndr]];
  const host=$('#specTable');host.replaceChildren();const tb=document.createElement('table'),tr=document.createElement('tr');['스펙','목표 하한 (편집)','모델 가정 / 예측','Cadence 측정','목표 대비 여유'].forEach(x=>tr.append(node('th',x)));tb.append(tr);
  for(const [key,unit,value]of rows){const row=document.createElement('tr'),td=document.createElement('td'),input=document.createElement('input');input.type='number';input.step='any';input.value=targets[key];input.style.width='100px';input.setAttribute('aria-label','목표 '+key);input.onchange=()=>{if(!Number.isFinite(Number(input.value)))return;targets[key]=Number(input.value);localStorage.setItem('circuit-spec-targets',JSON.stringify(targets));showTheory(p);};td.append(input,node('span',' '+unit));const margin=Number.isFinite(value)?value-targets[key]:null;const verdict=node('td',margin===null?'미계산':`${margin>=0?'만족':'미달'} ${fmt(margin)} ${unit}${key==='PM'?' · 가정값 비교만':''}`);verdict.className=margin===null?'unknown':margin>=0?'ok':'fail';row.append(node('td',key),td,node('td',Number.isFinite(value)?fmt(value)+' '+unit+(key==='SNDR'?' (예측)':' (가정)'):'미계산'),node('td','미측정'),verdict);tb.append(row);}host.append(tb);
  table($('#settlingTable'),['정착오차','필요 τ','τ 최대 [ns]','GBW 최소 [MHz]'],t.settling.map(r=>[r.error,fmt(r.ntau),fmt(r.tauMax*1e9),fmt(r.GBW/1e6)]));
  table($('#noiseTable'),['계산 항목','값'],[['전대역 열잡음',fmt(t.sigma*1e6)+' µVrms'],['대역내 열잡음',fmt(t.sigmaIB*1e6)+' µVrms'],['열잡음만의 SNR',fmt(t.snrThermal)+' dB'],...t.caps.map(r=>['SNR '+r.snr+' dB 필요 Cs',fmt(r.C*1e12)+' pF']),['권장 A0',fmt(t.A0recommended)+' dB'],['권장 SR (2×)',fmt(t.SRrecommended/1e6)+' V/µs']]);
 }
 function showModel(result){model=result;showTheory(result.conditions);const spec=s=>envelope(s.spectrum.f.slice(1).map((f,i)=>[f,10*Math.log10(Math.max(s.spectrum.psd[i+1]/.5,1e-30))]));chart($('#modelSpectrum'),[{name:'ideal',points:spec(result.ideal),color:'#a1adb5'},{name:'real 모델',points:spec(result.real)}],{xLabel:'주파수 [Hz]',yLabel:'dBFS/Hz',logX:true,vertical:[{value:result.theory.BW,name:'BW'}]});
  chart($('#amplitudeChart'),[{name:'모델 SNDR',points:result.amplitudes}],{xLabel:'입력 진폭 [dBFS]',yLabel:'SNDR [dB]',horizontal:[{value:targets.SNDR}]});
  cards($('#modelSummary'),[['ideal SNDR',fmt(result.ideal.sndr)+' dB','ENOB '+fmt(result.ideal.enob)],['real 모델 SNDR',fmt(result.real.sndr)+' dB','ENOB '+fmt(result.real.enob)],['ideal − real',fmt(result.ideal.sndr-result.real.sndr)+' dB','음수는 개선을 보장하지 않음'],['피크 SNDR',fmt(result.peak[1])+' dB',result.peak[0]+' dBFS에서'],['추정 DR',fmt(result.DR)+' dB',result.DRnote],['출력 포화',fmt(result.real.saturation*100)+' %','실제 입력 '+fmt(result.real.fin,7)+' Hz']]);
  $('#modelSweeps').replaceChildren();for(const s of result.sweeps){const box=node('div',''),plot=node('div','');box.append(node('h3',s.title),plot);$('#modelSweeps').append(box);chart(plot,[{name:s.title,points:s.points}],{xLabel:s.unit,yLabel:'SNDR [dB]',logX:!['A0','Vhyst'].includes(s.key),horizontal:[{value:result.ideal.sndr}]});}
  $('#modelStatus').textContent='모델 계산 완료 · PM 영향 미포함 · 점선은 ideal 기준 · 데이터는 모델 결과 저장으로 내보낼 수 있습니다.';
 }
 $('#calcTheory').onclick=()=>{try{showTheory(read());$('#modelStatus').textContent='설계 가정에 따른 계산입니다. Cadence 측정값이 아닙니다.';}catch(e){$('#modelStatus').textContent=e.message;}};
 const busy=value=>{$('#runModel').disabled=value;$('#calcTheory').disabled=value;$('#cancelModel').disabled=!value;$('#modelInputs').querySelectorAll('input').forEach(e=>e.disabled=value);};
 $('#runModel').onclick=()=>{try{const p=read();showTheory(p);worker=new Worker(new URL('./spec-worker.js',import.meta.url),{type:'module'});busy(true);$('#modelStatus').textContent='모델 계산 중…';worker.onmessage=e=>{if(e.data.progress)$('#modelStatus').textContent=e.data.progress+' 계산 중…';if(e.data.result||e.data.error){busy(false);worker.terminate();worker=null;if(e.data.error)$('#modelStatus').textContent=e.data.error;else showModel(e.data.result);}};worker.onerror=e=>{busy(false);$('#modelStatus').textContent='모델 실행 실패: '+e.message;worker?.terminate();worker=null;};worker.postMessage(p);}catch(e){$('#modelStatus').textContent=e.message;}};
 $('#cancelModel').onclick=()=>{worker?.terminate();worker=null;busy(false);$('#modelStatus').textContent='계산을 중지했습니다.';};
 function selectRuns(){const old=$('#runSelect').value;$('#runSelect').replaceChildren();runs.filter(r=>r.success&&r.measurements).forEach(r=>{const option=node('option',`${r.cell} · ${(r.overrides||[]).map(c=>c.key+'='+c.after).join(', ')||'원본'} · ${r.job?.slice(0,6)}`);option.value=r.job;$('#runSelect').append(option);});if([...$('#runSelect').options].some(o=>o.value===old))$('#runSelect').value=old;selectRun();}
 function selectRun(){loadRevision++;selected=runs.find(r=>r.job===$('#runSelect').value);wave=null;$('#signalSelect').replaceChildren();for(const m of selected?.measurements?.metrics||[]){const option=node('option',m.signal+' ['+m.unit+']');option.value=m.signal;$('#signalSelect').append(option);}if(selected?.measurements.metrics.some(m=>m.signal==='Vop'))$('#signalSelect').value='Vop';$('#timeStart').value=(selected?.measurements.time_start_s||0)*1000;$('#timeEnd').value=(selected?.measurements.time_end_s||0)*1000;
  $('#actualSweepKey').replaceChildren();const keys=[...new Set(runs.filter(r=>r.source_sha256===selected?.source_sha256).flatMap(r=>(r.overrides||[]).map(c=>c.key)))];for(const key of keys){const o=node('option',key);$('#actualSweepKey').append(o);}drawActualSweep();$('#timeChart').replaceChildren();$('#fftChart').replaceChildren();}
 function drawActualSweep(){const key=$('#actualSweepKey').value,signal=$('#signalSelect').value,metric=$('#actualMetric').value;if(!selected||!key){$('#actualSweep').textContent='같은 조건에서 변경한 파라미터의 실행이 필요합니다.';return;}
  const sameSource=runs.filter(r=>r.success&&r.cell===selected.cell&&r.source_sha256===selected.source_sha256);
  const linked=(selected.overrides||[]).filter(c=>c.key!==key&&sameSource.every(r=>r.overrides?.some(v=>v.key===key)&&r.overrides?.find(v=>v.key===c.key)?.after===r.overrides?.find(v=>v.key===key)?.after)).map(c=>c.key);
  const signature=r=>JSON.stringify((r.overrides||[]).filter(c=>c.key!==key&&!linked.includes(c.key)).map(c=>[c.key,c.after]).sort());const matches=runs.filter(r=>r.success&&r.cell===selected.cell&&r.source_sha256===selected.source_sha256&&signature(r)===signature(selected)&&r.measurements?.time_start_s===selected.measurements.time_start_s&&r.measurements?.time_end_s===selected.measurements.time_end_s);
  const points=matches.map(r=>[numeric(r.overrides?.find(c=>c.key===key)?.after),r.measurements.metrics.find(m=>m.signal===signal)?.[metric]]).filter(p=>p.every(Number.isFinite)).sort((a,b)=>a[0]-b[0]);
  if(points.length<2){$('#actualSweep').textContent='다른 조건을 고정한 비교 가능한 실행이 2개 이상 필요합니다. 연동 변경은 동일 단일 변수 스윕으로 간주하지 않습니다.';return;}
  chart($('#actualSweep'),[{name:signal+' '+metric,points}],{xLabel:key+' [SI]'+(linked.length?' · 연동 '+linked.join(', '):''),yLabel:selected.measurements.metrics.find(m=>m.signal===signal)?.unit||''});
 }
 async function drawWave(){if(!selected)return;const rev=++loadRevision,run=selected;$('#waveStatus').textContent='전체 파형 CSV를 읽는 중…';try{
  if(!wave){const result=await api('simulation-waveform',{job:run.job});if(rev!==loadRevision)return;const lines=result.csv.trim().split(/\r?\n/),headers=lines.shift().split(',');const parsed=lines.map(l=>l.split(',').map(Number));if(headers[0]!=='time_s'||headers.some(h=>h.includes('"'))||parsed.some(r=>r.length!==headers.length||!r.every(Number.isFinite)))throw Error('지원하지 않거나 손상된 CSV 형식입니다.');wave={headers,rows:parsed};}
  const start=Number($('#timeStart').value)/1000,end=Number($('#timeEnd').value)/1000;if(!Number.isFinite(start)||!Number.isFinite(end)||end<=start)throw Error('올바른 시작/끝 구간을 입력하세요.');const metric=run.measurements.metrics.find(m=>m.signal===$('#signalSelect').value),index=wave.headers.indexOf(metric.signal+'_'+metric.unit);if(index<0)throw Error('CSV에서 신호를 찾지 못했습니다.');const rows=wave.rows.filter(r=>r[0]>=start&&r[0]<=end);if(rows.length<16)throw Error('구간에 최소 16개 샘플이 필요합니다.');
  const names=[metric.signal,...['Vp','Vm','clk'].filter(n=>n!==metric.signal&&metric.unit==='V')];const series=names.map(name=>{const i=wave.headers.indexOf(name+'_'+metric.unit);return i<0?null:{name,points:envelope(rows.map(r=>[r[0]*1000,r[i]]))};}).filter(Boolean);chart($('#timeChart'),series,{xLabel:'시간 [ms]',yLabel:metric.unit});
  const N=2**Math.floor(Math.log2(Math.min(rows.length,32768))),fs=(N-1)/(rows.at(-1)[0]-rows[0][0]),y=new Float64Array(N);let j=1;for(let i=0;i<N;i++){const t=rows[0][0]+i/fs;while(j<rows.length-1&&rows[j][0]<t)j++;const a=rows[j-1],b=rows[j];y[i]=a[index]+(b[index]-a[index])*(t-a[0])/(b[0]-a[0]);}
  const s=spectrum(y,fs);chart($('#fftChart'),[{name:metric.signal+' · 선형 보간',points:envelope(s.f.slice(1).map((f,i)=>[f,10*Math.log10(Math.max(s.psd[i+1],1e-30))]))}],{xLabel:'주파수 [Hz]',yLabel:'dB('+metric.unit+'²/Hz)',logX:true});
  $('#waveStatus').textContent=`${run.cell} · ${rows.length}개 원본 샘플 · FFT ${N}점, Δf ${fmt(s.df)} Hz · 표시용 최소/최대 보존 축약 · ADC SNDR 미판정`;
 }catch(e){if(rev===loadRevision)$('#waveStatus').textContent='파형 읽기 실패: '+e.message;}}
 $('#loadRuns').onclick=async()=>{try{const data=await api('simulation-history');const merged=[...data.runs,...getRuns()];const seen=new Set();runs=merged.filter(r=>r.job&&!seen.has(r.job)&&seen.add(r.job)).slice(0,20);setRuns(runs);selectRuns();await drawWave();}catch(e){$('#waveStatus').textContent=e.message;}};
 $('#runSelect').onchange=()=>{selectRun();drawWave();};$('#signalSelect').onchange=()=>{drawActualSweep();drawWave();};$('#drawWave').onclick=drawWave;$('#actualSweepKey').onchange=drawActualSweep;$('#actualMetric').onchange=drawActualSweep;
 $('#exportSpecs').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify({conditions:read(),targets,model,cadenceRuns:runs},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='circuit-spec-report.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
 document.querySelectorAll('[data-panel]').forEach(button=>button.onclick=()=>{const spec=button.dataset.panel==='spec';$('#specDashboard').hidden=!spec;$('#experimentPanel').hidden=spec;document.querySelectorAll('[data-panel]').forEach(b=>b.classList.toggle('primary',b===button));});
 try{showTheory(read());}catch(e){$('#modelStatus').textContent=e.message;}
 selectRuns();$('#loadRuns').click();if(typeof Worker!=='undefined')$('#runModel').click();
 return {update(value){runs=value;selectRuns();}};
}
